const search=document.createElement('input');search.type='search';search.placeholder='Find an effect: eye, numbers, shoes, flip…';search.setAttribute('aria-label','Search sequence effects');panel.append(search);const list=document.createElement('div');panel.append(list);const aliases={'eye-portal':'eye zoom push through face iris','number-reel-1':'numbers date clock metal transition wipe','number-reel-2':'numbers date clock metal transition wipe','shoe-strip':'shoes row scroll white outline blue selection','shoe-turn':'shoe 3d rotate spikes product','photo-flip':'photo card paper flip picture','portrait-mono':'black white portrait camera push','portrait-color':'color portrait camera push','ruins-wide':'battlefield aftermath soldiers video devastation','ruins-close':'convoy military vehicles ruined street video aftermath','ruined-street':'fire war street final'};for(const effect of catalog.effects)for(const id of effect.instances)aliases[id]=[effect.name,...effect.aliases,effect.description].join(' ').toLowerCase();Object.assign(aliases,{'ruin-occlusion':'ruin building wall sideways occlusion','salvage-search':'walking searchlight helmet materials','cable-focus':'cables yellow highlight camera focus','salvage-overview':'rubble searcher materials overview','vertical-workshop-passage':'vertical down bicycle passage','wheel-trimmer':'bicycle wheel leather trimmer rotate label','shoe-walk-handoff':'shoes walking feet foreground occlusion','shoe-magnifier':'shoe magnifying glass lens zoom','shoe-evolution':'shoe diagram route dotted path','next-occlusion':'foreground next transition'});const render=()=>{list.replaceChildren();let age=0;for(const stage of fx.historyShots){const at=age;age+=Math.max(.05,stage.duration);if(!aliases[stage.id]||search.value.toLowerCase().split(/\s+/).some(q=>!(stage.id+' '+aliases[stage.id]).includes(q)))continue;toolButton(list,(stage.id==='portrait-dissolve'?'sideways passage':stage.id==='war-hold'?'parallax approach':stage.id.replaceAll('-',' '))+' · preview',()=>{seekDepot(historyState(0,fx).start+at/fx.historyRate);playing=true;document.querySelector('#play').textContent='Ⅱ'});}};search.oninput=render;render();
